import React, { useRef, useState, useEffect, useCallback } from 'react';
import { PencilIcon, EraserIcon, TextIcon, RulerIcon, SquareIcon, CompassIcon, TrashIcon, CloseIcon } from './icons';

enum Tool {
  Pencil = 'pencil',
  Pen = 'pen',
  FeltTip = 'felttip',
  Chalk = 'chalk',
  Eraser = 'eraser',
  Text = 'text'
}

interface Point {
  x: number;
  y: number;
}

const COLORS = [
  '#FFFFFF', '#000000', '#4F46E5', '#EF4444', '#10B981', '#F59E0B', '#8B5CF6', '#EC4899'
];

const TOOLS_CONFIG = {
  [Tool.Pencil]: { size: 2, opacity: 0.8 },
  [Tool.Pen]: { size: 4, opacity: 1 },
  [Tool.FeltTip]: { size: 8, opacity: 1 },
  [Tool.Chalk]: { size: 6, opacity: 0.6 },
  [Tool.Eraser]: { size: 20, opacity: 1 },
};

const Tableau: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [activeTool, setActiveTool] = useState<Tool>(Tool.Pencil);
  const [activeColor, setActiveColor] = useState(COLORS[0]);
  const [showRuler, setShowRuler] = useState(false);
  const [showSquare, setShowSquare] = useState(false);
  const [showProtractor, setShowProtractor] = useState(false);
  const [textInput, setTextInput] = useState<{ x: number; y: number; value: string } | null>(null);

  // Initialize Canvas Size
  useEffect(() => {
    const handleResize = () => {
      if (canvasRef.current && containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect();
        canvasRef.current.width = width;
        canvasRef.current.height = height;
      }
    };

    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const startDrawing = useCallback((e: React.MouseEvent | React.TouchEvent) => {
    if (activeTool === Tool.Text) {
      const rect = canvasRef.current?.getBoundingClientRect();
      if (rect) {
        const x = ('touches' in e ? e.touches[0].clientX : e.clientX) - rect.left;
        const y = ('touches' in e ? e.touches[0].clientY : e.clientY) - rect.top;
        setTextInput({ x, y, value: '' });
      }
      return;
    }

    setIsDrawing(true);
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) {
      const rect = canvasRef.current?.getBoundingClientRect();
      const x = ('touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX) - (rect?.left || 0);
      const y = ('touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY) - (rect?.top || 0);

      ctx.beginPath();
      ctx.moveTo(x, y);

      const config = TOOLS_CONFIG[activeTool as keyof typeof TOOLS_CONFIG];
      if (config) {
        ctx.lineWidth = config.size;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.strokeStyle = activeTool === Tool.Eraser ? 'var(--canvas-bg)' : activeColor;
        ctx.globalAlpha = config.opacity;

        if (activeTool === Tool.Chalk) {
          ctx.setLineDash([1, 4]); // Effect for chalk
        } else {
          ctx.setLineDash([]);
        }
      }
    }
  }, [activeTool, activeColor]);

  const draw = useCallback((e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing) return;
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) {
      const rect = canvasRef.current?.getBoundingClientRect();
      const x = ('touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX) - (rect?.left || 0);
      const y = ('touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY) - (rect?.top || 0);

      ctx.lineTo(x, y);
      ctx.stroke();
    }
  }, [isDrawing]);

  const stopDrawing = useCallback(() => {
    setIsDrawing(false);
    const ctx = canvasRef.current?.getContext('2d');
    ctx?.closePath();
  }, []);

  const clearCanvas = () => {
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx && canvasRef.current) {
      ctx.clearRect(0, 0, canvasRef.current.width, canvasRef.current.height);
    }
  };

  const handleTextInputSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (textInput && canvasRef.current) {
      const ctx = canvasRef.current.getContext('2d');
      if (ctx) {
        ctx.font = '20px sans-serif';
        ctx.fillStyle = activeColor;
        ctx.globalAlpha = 1;
        ctx.fillText(textInput.value, textInput.x, textInput.y);
      }
      setTextInput(null);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[var(--color-bg-primary)] overflow-hidden" ref={containerRef}>
      <style>{`
        :root { --canvas-bg: #ffffff; }
        .dark { --canvas-bg: #1e293b; }
      `}</style>

      {/* Toolbar */}
      <div className="bg-[var(--color-card-bg)] border-b border-[var(--color-border)] p-2 flex flex-wrap items-center justify-between gap-4 z-10 shadow-sm">
        <div className="flex items-center space-x-1 bg-[var(--color-bg-secondary)] p-1 rounded-lg">
          <ToolBtn active={activeTool === Tool.Pencil} onClick={() => setActiveTool(Tool.Pencil)} icon={<PencilIcon className="w-5 h-5" />} label="Crayon" />
          <ToolBtn active={activeTool === Tool.Pen} onClick={() => setActiveTool(Tool.Pen)} icon={<PencilIcon className="w-5 h-5 stroke-[3px]" />} label="Stylo" />
          <ToolBtn active={activeTool === Tool.Chalk} onClick={() => setActiveTool(Tool.Chalk)} icon={<div className="w-5 h-2 bg-gray-300 rounded-sm rotate-45" />} label="Craie" />
          <ToolBtn active={activeTool === Tool.FeltTip} onClick={() => setActiveTool(Tool.FeltTip)} icon={<div className="w-5 h-4 bg-gray-500 rounded-sm" />} label="Feutre" />
          <ToolBtn active={activeTool === Tool.Text} onClick={() => setActiveTool(Tool.Text)} icon={<TextIcon className="w-5 h-5" />} label="Texte" />
          <ToolBtn active={activeTool === Tool.Eraser} onClick={() => setActiveTool(Tool.Eraser)} icon={<EraserIcon className="w-5 h-5" />} label="Gomme" />
        </div>

        <div className="flex items-center space-x-2">
          {COLORS.map(color => (
            <button
              key={color}
              onClick={() => setActiveColor(color)}
              className={`w-6 h-6 rounded-full border-2 transition-transform hover:scale-110 ${activeColor === color ? 'border-[var(--color-accent)] scale-125' : 'border-transparent'}`}
              style={{ backgroundColor: color }}
            />
          ))}
        </div>

        <div className="flex items-center space-x-1">
          <ToolBtn active={showRuler} onClick={() => setShowRuler(!showRuler)} icon={<RulerIcon className="w-5 h-5" />} label="Règle" />
          <ToolBtn active={showSquare} onClick={() => setShowSquare(!showSquare)} icon={<SquareIcon className="w-5 h-5" />} label="Équerre" />
          <button onClick={clearCanvas} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="Effacer tout">
            <TrashIcon className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Drawing Area */}
      <div className="relative flex-grow cursor-crosshair touch-none select-none bg-[var(--canvas-bg)]">
        <canvas
          ref={canvasRef}
          onMouseDown={startDrawing}
          onMouseMove={draw}
          onMouseUp={stopDrawing}
          onMouseOut={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={draw}
          onTouchEnd={stopDrawing}
          className="absolute inset-0 w-full h-full"
        />

        {/* Instruments Overlays */}
        {showRuler && <DraggableInstrument type="ruler" onClose={() => setShowRuler(false)} />}
        {showSquare && <DraggableInstrument type="square" onClose={() => setShowSquare(false)} />}

        {/* Text Input Modal-like */}
        {textInput && (
          <div className="absolute z-20" style={{ left: textInput.x, top: textInput.y }}>
            <form onSubmit={handleTextInputSubmit} className="flex flex-col">
              <input
                autoFocus
                value={textInput.value}
                onChange={e => setTextInput({ ...textInput, value: e.target.value })}
                onBlur={handleTextInputSubmit}
                className="bg-transparent border-b-2 border-[var(--color-accent)] outline-none text-xl p-1 text-[var(--color-text-primary)]"
                placeholder="Taper ici..."
              />
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

