const DraggableInstrument: React.FC<{ type: 'ruler' | 'square'; onClose: () => void }> = ({ type, onClose }) => {
  const [pos, setPos] = useState({ x: 100, y: 100 });
  const [isDragging, setIsDragging] = useState(false);
  const offset = useRef({ x: 0, y: 0 });

  const handleStart = (e: React.MouseEvent | React.TouchEvent) => {
    setIsDragging(true);
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    offset.current = { x: clientX - pos.x, y: clientY - pos.y };
  };

  const handleMove = (e: MouseEvent | TouchEvent) => {
    if (!isDragging) return;
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    setPos({ x: clientX - offset.current.x, y: clientY - offset.current.y });
  };

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMove);
      window.addEventListener('mouseup', () => setIsDrawing(false));
      window.addEventListener('touchmove', handleMove);
      window.addEventListener('touchend', () => setIsDrawing(false));
    }
    return () => {
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('touchmove', handleMove);
    };
  }, [isDragging]);

  const setIsDrawing = (val: boolean) => setIsDragging(val);

  return (
    <div
      className="absolute cursor-move select-none z-10"
      style={{ left: pos.x, top: pos.y }}
      onMouseDown={handleStart}
      onTouchStart={handleStart}
    >
      <div className="relative">
        <button 
          onClick={(e) => { e.stopPropagation(); onClose(); }} 
          className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-md hover:scale-110 transition-transform z-20"
        >
          <CloseIcon className="w-3 h-3" />
        </button>
        {type === 'ruler' ? (
          <div className="w-64 h-12 bg-yellow-200/40 border border-yellow-500 rounded flex items-end justify-between px-2 pb-1 text-[8px] font-mono text-yellow-700 pointer-events-none">
            {[...Array(13)].map((_, i) => (
              <div key={i} className="flex flex-col items-center">
                <div className={`w-px bg-yellow-600 ${i % 5 === 0 ? 'h-4' : 'h-2'}`} />
                {i % 5 === 0 && <span>{i}cm</span>}
              </div>
            ))}
          </div>
        ) : (
          <div className="w-48 h-48 bg-blue-200/30 border-l-2 border-b-2 border-blue-500 relative pointer-events-none" style={{ clipPath: 'polygon(0 0, 0 100%, 100% 100%)' }}>
             <div className="absolute left-2 bottom-2 text-[10px] text-blue-700 font-bold">90°</div>
          </div>
        )}
      </div>
    </div>
  );
};

